implementation.cssAdaptation:
@keyframes ola-metric-enter { from { opacity: 0; transform: translateY(4px); } to { opacity: 1; transform: translateY(0); } }
@keyframes ola-axis-enter { from { opacity: 0; transform: translateY(6px); } to { opacity: 1; transform: translateY(0); } }
@keyframes ola-chart-reveal { from { transform: scaleX(0); } to { transform: scaleX(1); } }
.metric-readout { animation: ola-metric-enter 160ms cubic-bezier(0.16, 1, 0.3, 1) both; }
.chart-axis-labels { animation: ola-axis-enter 160ms cubic-bezier(0.16, 1, 0.3, 1) both; }
.chart-line { stroke-dasharray: none; }
.chart-reveal-mask { transform-origin: 0 0; animation: ola-chart-reveal 400ms linear backwards; }
@media (prefers-reduced-motion: reduce) { .metric-readout, .chart-axis-labels, .chart-reveal-mask { animation: none; transform: none; opacity: 1; } }
